# archive_prune <archive dir> <name> <keep>: keep the newest <keep> copies.
archive_prune() {
  local archive=$1 name=$2 keep=$3 f
  ls "$archive" | grep "^$name\.[0-9][0-9]*$" | sort | head -n -"$keep" | while read -r f; do
    rm -f "$archive/$f"
  done
}

